"""Checks of the hot-fire test-point analysis behind the E2 Test Explorer (pytest)."""
import math

import numpy as np
import pytest

from h2cea import config as C
from h2cea import hotfire as H
from h2cea.cea_si import point
from h2cea.operating_line import state


@pytest.fixture(scope="module")
def hw():
    return H.hardware_presets()["E2-REG-1"]


def synthetic(hw, mox=0.62, eta_c=0.93, eta_f=0.965, **kw):
    """A test point generated by the engine model with known efficiencies."""
    ox = H._ox_card(C.T_OX_NOM, C.P_TANK)
    s = state(mox, hw.At, eps=hw.eps, eta_c=eta_c, eta_f=eta_f, ox=ox)
    return s, H.new_test(test_id="T-001", hardware=hw.key, pc_bar=s["pc"], ox_flow_kg_s=mox, fuel_flow_kg_s=C.MDOT_FUEL,
                         thrust_N=s["F"], **kw)


def test_efficiencies_round_trip(hw):
    s, t = synthetic(hw)
    R = H.analyse(t)
    assert R["eta_cstar"] == pytest.approx(0.93, abs=5e-4)
    assert R["eta_cf_vac"] == pytest.approx(0.965, abs=5e-4)
    assert R["OF"] == pytest.approx(0.62 / C.MDOT_FUEL)
    # with the test's own efficiencies as the model, the model reproduces the test
    R2 = H.analyse(t, eta_cstar_model=0.93, eta_cf_model=0.965)
    assert abs(R2["pc_dev_pct"]) < 0.05 and abs(R2["thrust_dev_pct"]) < 0.1


def test_gauge_pressures_add_ambient(hw):
    s, t = synthetic(hw)
    t["inputs"]["pc_bar"] = s["pc"] - C.P_AMB
    t["pressures_gauge"] = True
    assert H.analyse(t)["eta_cstar"] == pytest.approx(0.93, abs=5e-4)


def test_ox_card_is_liquid_at_supply_pressure(hw):
    # the injector pressure is below the N2O saturation pressure; the reactant enthalpy must not change
    _, t = synthetic(hw)
    e0 = H.analyse(t)["eta_cstar"]
    t["inputs"]["p_ox_inj_bar"] = 26.0
    R = H.analyse(t)
    assert R["eta_cstar"] == pytest.approx(e0, rel=1e-9)
    assert not R["ox_liquid_at_inlet"]


def test_measured_throat_changes_area_and_eps(hw):
    s, t = synthetic(hw)
    t["inputs"]["throat_d_mm"] = hw.throat_d_mm * 1.02
    R = H.analyse(t)
    assert R["eta_cstar"] == pytest.approx(0.93 * 1.02 ** 2, rel=2e-3)
    assert R["eps"] == pytest.approx(hw.eps / 1.02 ** 2)


def test_injector_cda(hw):
    _, t = synthetic(hw, p_fuel_inj_bar=None)
    R0 = H.analyse(t)
    t["inputs"]["p_fuel_inj_bar"] = R0["pc_abs_bar"] + 6.0
    R = H.analyse(t)
    rho = R["rho_fuel"]
    assert R["CdA_fuel_mm2"] == pytest.approx(1e6 * C.MDOT_FUEL / math.sqrt(2 * rho * 6e5), rel=1e-9)
    assert R["stiff_fuel_pct"] == pytest.approx(600 / R["pc_abs_bar"])


def test_separation_at_low_pressure():
    flight = H.hardware_presets()["E2 flight"]
    _, t = synthetic(flight, mox=0.62)
    assert not H.analyse(t)["summerfield_sep"]
    t["inputs"]["pc_bar"] = 7.0
    R = H.analyse(t)
    assert R["summerfield_sep"] and R["x_sep_mm"] is not None
    assert R["nozzle"]["x_throat_mm"] < R["x_sep_mm"] <= R["nozzle"]["x_exit_mm"]


def test_missing_inputs_raise(hw):
    t = H.new_test(test_id="x")
    with pytest.raises(ValueError, match="missing"):
        H.analyse(t)


def test_water_jacket_fit_reproduces_heat(hw):
    s, t = synthetic(hw, water_flow_kg_s=1.0, water_T_in_C=18.0, water_T_out_C=50.0, water_p_in_bar=30.0)
    R = H.analyse(t)
    W = H.water_jacket(t, R, n_stations=150)
    assert W["Q_fit_kW"] == pytest.approx(R["Q_meas_kW"], rel=0.01)
    assert 0.5 < W["bartz_fit"] < 1.5
    assert W["Twg_max_fit_K"] < W["Twg_max_K"] if W["bartz_fit"] < 1 else True


def test_demo_trace_window_and_means(hw):
    df = H.demo_trace(burn_s=5.0)
    m = H.guess_columns(df.columns)
    assert {"time", "pc_bar", "ox_flow_kg_s", "fuel_flow_kg_s", "thrust_N"} <= set(m)
    b0, b1, s0, s1 = H.burn_window(df[m["time"]], df[m["pc_bar"]])
    assert b0 == pytest.approx(0.2, abs=0.2) and b1 == pytest.approx(4.9, abs=0.3)
    assert b0 < s0 < s1 < b1
    means = H.window_means(df, m, s0, s1)
    assert means["fuel_flow_kg_s"] == pytest.approx(0.20, rel=0.01)
    R = H.analyse(H.new_test(**{k: v for k, v in means.items() if not k.startswith("_")}))
    assert 0.9 < R["eta_cstar"] < 0.96


def test_burn_window_without_burn():
    t = np.linspace(0, 5, 500)
    assert H.burn_window(t, np.zeros_like(t)) is None


def test_save_and_load(tmp_path, hw):
    _, t = synthetic(hw, notes="first light")
    H.save_test(t, tmp_path)
    (loaded,) = H.load_tests(tmp_path)
    assert loaded["test_id"] == "T-001" and loaded["notes"] == "first light"
    assert H.analyse(loaded)["eta_cstar"] == pytest.approx(H.analyse(t)["eta_cstar"])


def test_cea_map_matches_point(hw):
    m = H.cea_map(hw.eps, pcs=[15.0, 20.0], ofs=[2.5, 3.0])
    ox = H._ox_card(C.T_OX_NOM, C.P_TANK)
    assert m["grid"]["cstar"][1][0] == pytest.approx(point(20.0, 2.5, round(hw.eps, 4), C.P_AMB, ox).cstar, rel=1e-6)
